TYPE STATES : (IDLE, OPENING, CLOSING, FAULT);
END_TYPE

FUNCTION_BLOCK FB
VAR_INPUT
    openBtn   : BOOL;
    closeBtn  : BOOL;
    openLimit : BOOL;
    closeLimit: BOOL;
    obstacle  : BOOL;
END_VAR
VAR_OUTPUT
    motorUp   : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL;
END_VAR
VAR
    state       : STATES := IDLE;
    prevOpenBtn : BOOL := FALSE;
    prevCloseBtn: BOOL := FALSE;
    openRising  : BOOL;
    closeRising : BOOL;
END_VAR

    // Detect rising edges
    openRising  := openBtn AND NOT prevOpenBtn;
    closeRising := closeBtn AND NOT prevCloseBtn;

    // State machine
    CASE state OF
        IDLE:
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := FALSE;

            IF openRising AND NOT openLimit THEN
                state := OPENING;
            ELSIF closeRising AND NOT closeLimit THEN
                state := CLOSING;
            END_IF

        OPENING:
            IF obstacle THEN
                // Stop motor and go to fault
                motorUp   := FALSE;
                motorDown := FALSE;
                errorFlag := TRUE;
                state := FAULT;
            ELSE
                motorUp   := TRUE;
                motorDown := FALSE;
                IF openLimit THEN
                    state := IDLE;
                END_IF
            END_IF

        CLOSING:
            IF obstacle THEN
                // Reverse to opening immediately
                motorUp   := TRUE;
                motorDown := FALSE;
                state := OPENING;
            ELSE
                motorUp   := FALSE;
                motorDown := TRUE;
                IF closeLimit THEN
                    state := IDLE;
                END_IF
            END_IF

        FAULT:
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := TRUE;

            // Reset only on simultaneous rising edges of both buttons and obstacle cleared
            IF openRising AND closeRising AND NOT obstacle THEN
                state := IDLE;
                errorFlag := FALSE;
            END_IF
    END_CASE

    // Update button history for next scan
    prevOpenBtn  := openBtn;
    prevCloseBtn := closeBtn;

END_FUNCTION_BLOCK
